message.content:
{
  "definition_simple": "電車や列車が走るために敷いてある鉄のレールとその道。",
  "definition_standard": "鉄道車両を走行させるため、レール・枕木・道床などで構成された通路。",
  "pos": "名詞",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "電車が線路を走っています。"
    },
    {
      "tier": "T1",
      "sentence": "線路の近くで遊んではいけません。"
    },
    {
      "tier": "T2",
      "sentence": "危ないですから、線路に入ってはいけません。"
    },
    {
      "tier": "T2",
      "sentence": "家のすぐ隣に線路があるので、列車の音がよく聞こえます。"
    },
    {
      "tier": "T3",
      "sentence": "遮断機が下りている間は、線路を渡ってはいけません。"
    },
    {
      "tier": "T3",
      "sentence": "大雨の影響で線路に土砂が流れ込み、電車の運転が見合わされている。"
    },
    {
      "tier": "T4",
      "sentence": "列車の安全運行を支えるため、作業員たちが深夜に線路の保守点検を行っている。"
    },
    {
      "tier": "T4",
      "sentence": "かつて木材を運んでいた廃線跡の線路沿いには、春になると見事な桜並木が広がる。"
    },
    {
      "tier": "T5",
      "sentence": "急カーブの多い山岳区間では、線路と車輪の摩耗を防ぐために自動散水装置が整備されている。"
    },
    {
      "tier": "T6",
      "sentence": "新幹線が時速三百キロで安全に走行できるよう、継ぎ目のないロングレールを用いた堅牢な線路構造が採用されている。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "primary_collocate": "沿い",
  "collocation_distractors": [
    {
      "word": "通り",
      "explanation": "「通り」は市街地の一般的な街路（道）に後続する語であり、鉄道の専用路である線路には付接しません。"
    },
    {
      "word": "舗装",
      "explanation": "「舗装」はアスファルトやコンクリートを敷き固める道路工事に用いる語で、バラストやレールを敷設する線路には使いません。"
    },
    {
      "word": "歩道",
      "explanation": "線路は鉄道車両専用であり歩行者の通行が禁止されているため、「線路歩道」のような複合語は成立しません。"
    }
  ],
  "collocation_wrong_collocate": "車道",
  "cloze_distractors": [
    {
      "word": "航路",
      "explanation": "「航路」は船舶や航空機が通る水上・空中の交通路を指すため、地上の鉄道を走る文脈には合いません。"
    },
    {
      "word": "回路",
      "explanation": "「回路」は電流が流れる環状の電気的道筋などを指し、鉄道の物理的軌道とは全く異なる概念です。"
    },
    {
      "word": "通路",
      "explanation": "「通路」は建物内や乗り物内の人が通る通路を指す一般的な語であり、列車が走る専用の軌道を指す言葉としては不適切です。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "週末は線路をドライブして海まで行きました。",
      "explanation": "「線路」は鉄道車両専用の軌道であり、一般自動車の運転対象にはならないため意味的に誤りです（「道路」を用いるべき）。"
    },
    {
      "sentence": "線路をきれいに拭いてから食卓の上に置いた。",
      "explanation": "「線路」は屋外に敷設される大規模な鉄道土木構造物であり、卓上に置くような小型の可動物体として扱うのは語義・選択制限に反します。"
    },
    {
      "sentence": "朝のジョギングコースとして駅前の線路を走った。",
      "explanation": "線路内への立ち入りは法律で厳しく禁止されており、通常のランニング・歩行路として「線路を走る」と表現するのは常識的・コロケーション的に誤用です。"
    }
  ],
  "spot_incorrect": {
    "sentence": "危ないですから、絶対に線路で入らないでください。",
    "error_description": "侵入や進入の到達点・帰着点を示す助詞として「で」を用いるのは誤りで、「に」が適切です。",
    "corrected": "危ないですから、絶対に線路に入らないでください。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {
      "form": "線路る",
      "explanation": "名詞「線路」を五段動詞化しようとした不自然な造語です。"
    },
    {
      "form": "線路的",
      "explanation": "純粋な物理インフラ名詞「線路」に接尾辞「的」を付けた存在しない形容動詞形です。"
    },
    {
      "form": "線路さ",
      "explanation": "名詞に直接接尾辞「さ」を付けて状態の度合いを表そうとした非文法的な形態です。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "軌道",
      "relation": "synonym"
    },
    {
      "word": "レール",
      "relation": "synonym"
    },
    {
      "word": "鉄路",
      "relation": "synonym"
    },
    {
      "word": "道路",
      "relation": "antonym"
    }
  ],
  "particle_candidates": [
    {
      "particle": "に",
      "correct": true,
      "explanation": "進入・立ち入りの帰着点・到達点を示す助詞として「に」が正確です。"
    },
    {
      "particle": "で",
      "correct": false,
      "explanation": "「で」は動作が行われる場所を示しますが、境界を越えて内部へ移動する「立ち入る」の着地点を示すことはできません。"
    },
    {
      "particle": "を",
      "correct": false,
      "explanation": "「を」は移動経路や通過点を表しますが、「立ち入る」を動詞とした場合に進入先を直接目的語のように取るのは誤用です。"
    },
    {
      "particle": "から",
      "correct": false,
      "explanation": "「から」は離脱の起点を示すため、「入る」という進入の意味と方向性が正反対になってしまいます。"
    }
  ]
}
